// Adapted from d454f2c:.github/r15-noble/consumer-proof.mjs.
// This proves the immutable candidate only, never historical/current PR heads.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFile, writeFile, mkdir, mkdtemp, copyFile } from 'node:fs/promises';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(process.env.GITHUB_WORKSPACE, 'candidate');
const proof = join(process.env.RUNNER_TEMP, 'u1-integrated/proof');
const scratch = await mkdtemp(join(process.env.RUNNER_TEMP, 'u1-consumers-'));
const execute = (file, args, cwd) => execFileSync(file, args, { cwd, encoding: 'utf8', timeout: 600000,
  maxBuffer: 20_000_000, stdio: ['ignore', 'pipe', 'pipe'] });
const imported = file => import(pathToFileURL(join(source, 'tools/contracts/src', file)));
assert.equal(execute('git', ['rev-parse', 'HEAD'], source).trim(), process.env.CANDIDATE);
const { createBoundedGeneratorRunner } = await imported('bounded-generators.mjs');
const { createPinnedGeneratorRunner } = await imported('generators.mjs');
const { normalizeGeneratedConsumer, digestDirectory } = await imported('generation.mjs');
const profile = JSON.parse(await readFile(join(source, 'contracts/samples/walking-skeleton/governance/generation-profile.json')));
const host = createPinnedGeneratorRunner(source);
const measurements = [];
const bounded = createBoundedGeneratorRunner(source, { standardsImage: process.env.STOCKSENSE_STANDARDS_IMAGE,
  kiotaImage: process.env.STOCKSENSE_KIOTA_IMAGE, onMeasurement: row => measurements.push(row) });
const consumers = [];
for (const consumer of profile.consumers) {
  const baseline = join(scratch, 'host', consumer.consumerId);
  await mkdir(baseline, { recursive: true });
  host(consumer, baseline);
  await normalizeGeneratedConsumer(consumer, baseline);
  const before = await digestDirectory(baseline);
  assert.deepEqual(before, consumer.expectedOutputs);
  const runs = [];
  let generated;
  for (let pass = 1; pass <= 2; pass++) {
    const folder = join(proof, 'generated', `pass${pass}`, consumer.consumerId);
    await mkdir(folder, { recursive: true });
    bounded(consumer, folder);
    await normalizeGeneratedConsumer(consumer, folder);
    const after = await digestDirectory(folder);
    assert.deepEqual(after, before, 'Every generated byte and lock must remain unchanged');
    runs.push(after);
    generated = folder;
  }
  assert.deepEqual(runs[0], runs[1]);
  if (consumer.generator === 'kiota') {
    assert.equal(consumer.generatorVersion, '1.38.0');
    const compile = join(scratch, 'compile');
    await mkdir(compile);
    await copyFile(join(here, 'consumer-fixture.cs'), join(compile, 'Program.cs'));
    await writeFile(join(compile, 'Check.csproj'), '<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup><ItemGroup><PackageReference Include="Microsoft.Kiota.Bundle" Version="2.1.6"/><Compile Include="/generated/**/*.cs"/></ItemGroup></Project>');
    const mounts = ['--rm', '--pull=never', '--user', `${process.getuid()}:${process.getgid()}`,
      '--cpus=1', '--memory=2g', '--memory-swap=2g', '--pids-limit=256', '--cap-drop=ALL',
      '--security-opt=no-new-privileges', '-e', 'HOME=/tmp', '-e', 'DOTNET_CLI_HOME=/tmp',
      '-e', 'NUGET_PACKAGES=/check/packages', '-v', `${compile}:/check`,
      '-v', `${join(generated, 'dotnet-client')}:/generated:ro`, '-w', '/check'];
    const restore = execute('docker', ['run', ...mounts, process.env.SDK, 'dotnet', 'restore', 'Check.csproj'], scratch);
    await writeFile(join(proof, 'consumer-restore.txt'), restore);
    await copyFile(join(compile, 'obj/project.assets.json'), join(proof, 'consumer-assets.json'));
    const transcript = execute('docker', ['run', ...mounts, '--network=none', process.env.SDK,
      'dotnet', 'run', '--no-restore', '--project', 'Check.csproj'], scratch);
    assert.match(transcript, /Session request, response deserialization and review payload serialization passed/);
    await writeFile(join(proof, 'consumer-compile.txt'), transcript);
  }
  consumers.push({ id: consumer.consumerId, generator: consumer.generator, version: consumer.generatorVersion, before, runs });
}
assert.equal(consumers.reduce((count, consumer) => count + Object.keys(consumer.runs[0]).length, 0), 107);
assert.equal(measurements.length, 6);
for (const row of measurements) assert.ok(row.elapsedMs <= 120000 && row.peakBytes > 0 && row.peakBytes <= 2147483648);
await writeFile(join(proof, 'consumer-proof.json'), JSON.stringify({ diagnosticOnly: true,
  candidate: process.env.CANDIDATE, sdk: process.env.SDK, standardsImage: process.env.STOCKSENSE_STANDARDS_IMAGE,
  kiotaImage: process.env.STOCKSENSE_KIOTA_IMAGE, profileSourceRevision: profile.sourceRevision,
  profileBlob: execute('git', ['rev-parse', 'HEAD:contracts/samples/walking-skeleton/governance/generation-profile.json'], source).trim(),
  consumers, measurements }, null, 2) + '\n');
console.log('Immutable candidate: two clean bounded 107-output generations and generated C# fixture passed');
